UPDATE conversation
SET title = #{title}
WHERE id = #{id}

UPDATE conversation
SET processing_started_at = #{now}
WHERE id = #{id}
  AND (
    processing_started_at IS NULL
    OR processing_completed_at >= processing_started_at
    OR processing_started_at < #{staleBefore}
  )

UPDATE conversation
SET processing_completed_at = #{now}
WHERE id = #{id}
